package com.holidayhomemanager.app;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.provider.CalendarContract;import com.getcapacitor.*;import com.getcapacitor.annotation.*;import androidx.activity.result.ActivityResult;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;
@CapacitorPlugin(name="Archive") public class ArchivePlugin extends Plugin {
@PluginMethod public void select(PluginCall call){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(call,i,"selected");}
@ActivityCallback private void selected(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK){call.reject("Selezione annullata");return;}try{Uri u=result.getData().getData();getContext().getContentResolver().takePersistableUriPermission(u,result.getData().getFlags()&3);String s;try(InputStream in=getContext().getContentResolver().openInputStream(u)){s=new String(in.readAllBytes(),StandardCharsets.UTF_8);}getContext().getSharedPreferences("archive",0).edit().putString("uri",u.toString()).apply();JSObject o=new JSObject();o.put("data",s);call.resolve(o);}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void create(PluginCall call){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"HolidayHomeManager.json");startActivityForResult(call,i,"created");}
@ActivityCallback private void created(PluginCall call,ActivityResult r){if(call==null)return;if(r.getResultCode()!=Activity.RESULT_OK){call.reject("Annullato");return;}try{Uri u=r.getData().getData();getContext().getContentResolver().takePersistableUriPermission(u,r.getData().getFlags()&3);getContext().getSharedPreferences("archive",0).edit().putString("uri",u.toString()).apply();write(call);}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public synchronized void write(PluginCall call){try{String s=getContext().getSharedPreferences("archive",0).getString("uri",null);if(s==null){call.reject("Archivio non configurato");return;}try(OutputStream out=getContext().getContentResolver().openOutputStream(Uri.parse(s),"wt")){out.write(call.getString("data","").getBytes(StandardCharsets.UTF_8));}call.resolve();}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void calendar(PluginCall call){try{long start=LocalDateTime.parse(call.getString("date")+"T"+call.getString("time")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();Intent i=new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,call.getString("title")).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,start+1800000);getActivity().startActivity(i);call.resolve();}catch(Exception e){call.reject(e.toString());}}
}